import{_ as s,l as o,o as e,c as i,v as t,p as l,x as r,d as p,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const w=JSON.parse('{"title":"Gamma swap","description":"","frontmatter":{"title":"Gamma swap","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gamma-swap.md","filePath":"quant/gamma-swap.md","lastUpdated":1789023840000}'),E={name:"quant/gamma-swap.md"};function h(_,a,c,u,f,B){const m=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="gamma-swap" tabindex="-1">Gamma swap <a class="header-anchor" href="#gamma-swap" aria-label="Permalink to &quot;Gamma swap&quot;">​</a></h1><div class="epigraph"><p>方差互换按 $1/K^2$ 加权香草条带；Gamma 互换按 $1/K$ 加权，使已实现方差的权重跟现价走，对冲的是价格加权的二次变差。</p><footer>—— 方差互换复制见 Carr–Madan 与 Demeterfi–Derman–Kamal–Zou；Gamma swap 的条带权见波动率衍生文献对 price-weighted variance 的定义</footer></div><p><a href="/quant/autocallable">上一课</a>把路径依赖收在零售障碍结构。本课回到波动率产品线：主干 <a href="/quant/variance-swap-vix">方差互换与 VIX</a> 已经把对数合约与 \\(1/K^2\\) 条带写清。缺口是 <strong>Gamma swap</strong>：已实现部分按收益贡献与 \\(S\\) 成正比加权，复制权从 \\(1/K^2\\) 变成 \\(1/K\\)。后课相关互换再把对象从单资产二次变差换成 \\(\\rho\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>方差互换支付 \\(\\frac{1}{T}\\sum r_i^2-K_{\\mathrm{var}}\\)，每笔对数收益等权。标的大涨之后，同样 1% 的收益对卖方的 Gamma 与未对冲方差一样大，但名本未随价格放大。Gamma swap 把权重改成与现价成正比（实现上常用 \\(\\frac{S_{i-1}}{S_0}r_i^2\\) 一类约定），使对冲账户里的 Gamma 更接近「持有随 \\(S\\) 放大的期权条带」。问题是：公平执行价不再等于对数合约，而等于<strong>价格加权</strong>的欧式条带，对偏斜的暴露从方差互换的下侧 \\(1/K^2\\) 转向更靠近 ATM 与上侧。</p><p>把 Gamma swap 当「方差互换换个名字」，会在微笑陡的指数上把执行价定错，也会把对冲用的期权权重用错。</p><h3 id="条带权决定吃哪一段微笑" tabindex="-1">条带权决定吃哪一段微笑 <a class="header-anchor" href="#条带权决定吃哪一段微笑" aria-label="Permalink to &quot;条带权决定吃哪一段微笑&quot;">​</a></h3><p>Carr–Madan 静态复制：收益 \\(f(S_T)\\) 由 \\(f&#39;&#39;\\) 对香草积分。方差互换对应 \\(f=\\ln\\)，权 \\(\\propto 1/K^2\\)，深度价外看跌权重大。Gamma swap 对应更接近 \\(S\\ln S\\) 一类，权 \\(\\propto 1/K\\)，看跌权重相对减轻。因此 Gamma swap 的公平波动通常高于或低于方差互换，取决于偏斜形态——差本身是一个偏斜仓位，不是噪声。</p><p><span class="marginnote">名称来自对冲：方差互换的瞬时 Gamma 随 \\(1/S^2\\) 变，Delta 对冲后对 \\(S\\) 的依赖与交易员「Gamma」直觉不完全一致；价格加权后更接近名义随现价走的 Gamma 账户。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在离散执行价网格上，用 \\(1/K\\) 权对 OTM 香草求和，加远期与现金项，得到公平 Gamma 方差，再开方报成波动（若市场习惯如此）。离散采样、跳、分红修正的精神与方差互换相同，系数不同，不要复用 \\(1/K^2\\) 的实现代码只改名字。有限执行价截断对 \\(1/K\\) 与 \\(1/K^2\\) 的敏感不同：下侧缺执行价时，方差互换缺得更多。</p><p>对冲：持有 \\(1/K\\) 条带并动态对冲 Delta。与方差互换簿之间的价差，主要是偏斜与跳。不要用 VIX 期货去对冲 Gamma swap 当「同一个 vol」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>二次变差的权若随 \\(S\\) 放大，大涨路径贡献更多已实现，大跌路径贡献相对方差互换更少（因为权随 \\(S\\) 降）。陡峭的负偏斜下，方差互换更吃下侧看跌；Gamma swap 相对「更 ATM」。两者的价差于是是交易偏斜的一种方式，而不必直接做风险反转。</p>',14)),(e(),l(d,null,{default:r(()=>[n(m,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Var%5B%22%E6%96%B9%E5%B7%AE%E4%BA%92%E6%8D%A2%20%E6%9D%83%201%2FK%5E2%22%5D%20--%3E%20PutW%5B%22%E6%B7%B1%E5%BA%A6%E7%9C%8B%E8%B7%8C%E6%9D%83%E9%87%8D%E5%A4%A7%22%5D%0A%20%20Gam%5B%22Gamma%20swap%20%E6%9D%83%201%2FK%22%5D%20--%3E%20AtmW%5B%22%E6%9D%83%E6%9B%B4%E9%9D%A0%E8%BF%91%20ATM%22%5D%0A%20%20PutW%20--%3E%20Skew%5B%22%E5%AF%B9%E8%B4%9F%E5%81%8F%E6%96%9C%E6%9B%B4%E6%95%8F%E6%84%9F%22%5D%0A%20%20AtmW%20--%3E%20Diff%5B%22%E4%B8%8E%E6%96%B9%E5%B7%AE%E4%BA%92%E6%8D%A2%E7%9A%84%E4%BB%B7%E5%B7%AE%E6%98%AF%E5%81%8F%E6%96%9C%E4%BB%93%22%5D%0A%20%20Skew%20--%3E%20Diff%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>合同必须写清：用何种对数收益、是否用收盘、是否除权、名义是方差点还是波动点、权是 \\(S_{i-1}/S_0\\) 还是连续 \\(S_t\\)。商品与外汇的「现价」还涉及远期滚动。流动性：Gamma swap 远薄于方差互换与 VIX，复制要用更宽的条带，买卖价差会吃掉理论价差。</p><p>本课不把 Gamma swap 写成「更好的方差互换」。它是不同的 \\(f&#39;&#39;\\)，服务不同的对冲账户。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Gamma swap 复制权是 \\(1/K\\)，方差互换是 \\(1/K^2\\)；公平执行价对偏斜的暴露不同。</li><li>与方差互换的价差本身是偏斜仓位。</li><li>实现不要复用方差互换代码只改标签；截断与跳的修正系数都不同。</li><li>出处：方差复制见 Carr and Madan, 1998 与 Demeterfi et al., 1999；价格加权方差的条带权见波动率衍生标准处理。</li></ul>',5))])}const S=s(E,[["render",h]]);export{w as __pageData,S as default};
